#
# Constraints to ensure sizable inputs.
#
##
class NodeGoalVisitor(DerivationTreeVisitor):
    def __init__(self):
        self.node_count = 0

    def generic_visit(self, node):
        self.node_count += 1
        for child in getattr(node, 'children', []):
            self.visit(child)

def num_violations_validity_only(tree, should_print = False):

    # Actual constraints visitors

    # decl collector
    declaration_collector = DeclarationCollector()
    declaration_collector.visit(tree)

    if should_print:
        print("=== Declaration Collector ===")
        print("Variable Symbol Table:")
        for (var_name, scope), var_type in declaration_collector.var_symbol_table.symbols.items():
            print(f"  {var_name} @ {scope}: {var_type}")
        print("Function Symbol Table:")
        for (func_name, scope), (param_types, return_type) in declaration_collector.func_symbol_table.symbols.items():
            print(f"  {func_name} @ {scope}: params {param_types} -> {return_type}")
        print("Struct Definitions:")
        for struct_name, fields in declaration_collector.struct_definitions.items():
            field_str = ', '.join([f"{name}: {type}" for name, type in fields])
            print(f"  {struct_name}: {field_str}")
        # Also print any violations found during declaration collection
        for var in declaration_collector.violations:
            print(f"Violation: {var}")

    # def-use
    def_use_visitor = DefUseVisitor()
    def_use_visitor.symbol_table = declaration_collector.var_symbol_table
    def_use_visitor.function_table = declaration_collector.func_symbol_table
    def_use_visitor.struct_definitions = declaration_collector.struct_definitions
    def_use_visitor.visit(tree)

    if should_print:
        print("=== Def-Use Visitor ===")
        for var in def_use_visitor.violations:
            print(f"Violation: {var}")

    # return only in functions
    return_in_func_visitor = ConstraintVisitorReturnInFunc()
    return_in_func_visitor.visit(tree)

    if should_print:
        print("=== Return In Function Visitor ===")
        for var in return_in_func_visitor.violations:
            print(f"Violation: {var}")

    # no duplicate struct fields
    no_duplicate_struct_fields_visitor = ConstraintVisitorNoDuplicateStructFields()
    no_duplicate_struct_fields_visitor.visit(tree)  

    if should_print:
        print("=== No Duplicate Struct Fields Visitor ===")
        for var in no_duplicate_struct_fields_visitor.violations:
            print(f"Violation: {var}")

    # struct field access
    struct_access_visitor = ConstraintVisitorStructAccess()
    struct_access_visitor.var_symbol_table = declaration_collector.var_symbol_table
    struct_access_visitor.struct_definitions = declaration_collector.struct_definitions
    struct_access_visitor.visit(tree)

    if should_print:
        print("=== Struct Access Visitor ===")
        for var in struct_access_visitor.violations:
            print(f"Violation: {var}")

    # no void decls
    no_void_decl_visitor = ConstraintVisitorNoVoidDecl()
    no_void_decl_visitor.visit(tree)

    if should_print:
        print("=== No Void Declarations Visitor ===")
        for var in no_void_decl_visitor.violations:
            print(f"Violation: {var}")

    # struct expr only in decls
    struct_expr_rhs_of_decl_visitor = ConstraintVisitorStructExprRHSOfDecl()
    struct_expr_rhs_of_decl_visitor.visit(tree)

    if should_print:
        print("=== Struct Expr RHS Of Decl Visitor ===")
        for var in struct_expr_rhs_of_decl_visitor.violations:
            print(f"Violation: {var}")

    # no empty structs
    no_empty_struct_visitor = ConstraintVisitorNoEmptyStruct()
    no_empty_struct_visitor.visit(tree)

    if should_print:
        print("=== No Empty Struct Visitor ===")
        for var in no_empty_struct_visitor.violations:
            print(f"Violation: {var}")

    # type checking
    type_check_visitor = ConstraintVisitorTypeCheck()
    try:
        type_check_visitor.var_symbol_table = declaration_collector.var_symbol_table
        type_check_visitor.function_table = declaration_collector.func_symbol_table
        type_check_visitor.struct_definitions = declaration_collector.struct_definitions
        type_check_visitor.visit(tree)
    except Exception as e:
        # print the traceback
        traceback.print_exc()   

    if should_print:
        print("=== Type Check Visitor ===")
        for var in type_check_visitor.violations:
            print(f"Violation: {var}")

    # For debugging, just return 0 so we can look and see
    # what the counts are
    # return 0

    # Try just the node goal visitor
    # This will never produce anything.
    # return 1 if node_goal_visitor.node_count < 1000 else 0

    # Return number of violations
    return len(def_use_visitor.violations) + \
           len(return_in_func_visitor.violations) + \
           len(struct_access_visitor.violations) + \
           len(no_void_decl_visitor.violations) + \
           len(struct_expr_rhs_of_decl_visitor.violations) + \
           len(no_empty_struct_visitor.violations) + \
           len(type_check_visitor.violations) + \
           len(declaration_collector.violations) + \
           len(no_duplicate_struct_fields_visitor.violations)

class SizeConstraintVisitor(DerivationTreeVisitor):
    def __init__(self):
        self.struct_count = 0
        self.function_count = 0
        self.statement_count = 0
        self.violations = []

    # <struct_def> ::= "struct" <sep> <struct_name> <sep> "{" "\n" <field_def_list_e> "\n" "}" ;
    def visit_struct_def(self, node):
        self.struct_count += 1
        if self.struct_count > 1:
            self.violations.append("too_many_structs")
        self.generic_visit(node)

    # <fn_def> ::= <ttype> <sep> <fn_kwd> <sep> <fn_name> "(" <param_list_e> ")" <sep> "{" <sep> <fn_body_e> <sep> "}" ;
    def visit_fn_def(self, node):
        self.function_count += 1
        if self.function_count > 1:
            self.violations.append("too_many_functions")
        self.generic_visit(node)

    # <stmt> ::= <decl> | <assignment> | <fn_call_stmt> | <return_stmt> | <expr_stmt> ;
    def visit_stmt(self, node):
        self.statement_count += 1
        self.generic_visit(node)

# Constraints for the lang grammar.
def num_violations_size_and_validity(tree, should_print = False):

    # First, goal visitors.
    # node_goal_visitor = NodeGoalVisitor()
    # node_goal_visitor.visit(tree)
    # if should_print:
    #     print("=== Node Goal Visitor ===")
    #     print("Node Count:", node_goal_visitor.node_count)

    reasonable_size_visitor = SizeConstraintVisitor()
    reasonable_size_visitor.visit(tree)

    if should_print:
        print("=== Reasonable Size Visitor ===")
        print("Struct Count:", reasonable_size_visitor.struct_count)
        print("Function Count:", reasonable_size_visitor.function_count)
        print("Statement Count:", reasonable_size_visitor.statement_count)
        for var in reasonable_size_visitor.violations:
            print(f"Violation: {var}")

    # If there aren't enough statements, register another violation
    if reasonable_size_visitor.statement_count < 5:
        reasonable_size_visitor.violations.append("too_few_statements")

    # Actual constraints visitors

    # decl collector
    declaration_collector = DeclarationCollector()
    declaration_collector.visit(tree)

    if should_print:
        print("=== Declaration Collector ===")
        print("Variable Symbol Table:")
        for (var_name, scope), var_type in declaration_collector.var_symbol_table.symbols.items():
            print(f"  {var_name} @ {scope}: {var_type}")
        print("Function Symbol Table:")
        for (func_name, scope), (param_types, return_type) in declaration_collector.func_symbol_table.symbols.items():
            print(f"  {func_name} @ {scope}: params {param_types} -> {return_type}")
        print("Struct Definitions:")
        for struct_name, fields in declaration_collector.struct_definitions.items():
            field_str = ', '.join([f"{name}: {type}" for name, type in fields])
            print(f"  {struct_name}: {field_str}")
        # Also print any violations found during declaration collection
        for var in declaration_collector.violations:
            print(f"Violation: {var}")

    # def-use
    def_use_visitor = DefUseVisitor()
    def_use_visitor.symbol_table = declaration_collector.var_symbol_table
    def_use_visitor.function_table = declaration_collector.func_symbol_table
    def_use_visitor.struct_definitions = declaration_collector.struct_definitions
    def_use_visitor.visit(tree)

    if should_print:
        print("=== Def-Use Visitor ===")
        for var in def_use_visitor.violations:
            print(f"Violation: {var}")

    # return only in functions
    return_in_func_visitor = ConstraintVisitorReturnInFunc()
    return_in_func_visitor.visit(tree)

    if should_print:
        print("=== Return In Function Visitor ===")
        for var in return_in_func_visitor.violations:
            print(f"Violation: {var}")

    # no duplicate struct fields
    no_duplicate_struct_fields_visitor = ConstraintVisitorNoDuplicateStructFields()
    no_duplicate_struct_fields_visitor.visit(tree)

    # struct field access
    struct_access_visitor = ConstraintVisitorStructAccess()
    struct_access_visitor.var_symbol_table = declaration_collector.var_symbol_table
    struct_access_visitor.struct_definitions = declaration_collector.struct_definitions
    struct_access_visitor.visit(tree)

    if should_print:
        print("=== Struct Access Visitor ===")
        for var in struct_access_visitor.violations:
            print(f"Violation: {var}")

    # no void decls
    no_void_decl_visitor = ConstraintVisitorNoVoidDecl()
    no_void_decl_visitor.visit(tree)

    if should_print:
        print("=== No Void Declarations Visitor ===")
        for var in no_void_decl_visitor.violations:
            print(f"Violation: {var}")

    # struct expr only in decls
    struct_expr_rhs_of_decl_visitor = ConstraintVisitorStructExprRHSOfDecl()
    struct_expr_rhs_of_decl_visitor.visit(tree)

    if should_print:
        print("=== Struct Expr RHS Of Decl Visitor ===")
        for var in struct_expr_rhs_of_decl_visitor.violations:
            print(f"Violation: {var}")

    # no empty structs
    no_empty_struct_visitor = ConstraintVisitorNoEmptyStruct()
    no_empty_struct_visitor.visit(tree)

    if should_print:
        print("=== No Empty Struct Visitor ===")
        for var in no_empty_struct_visitor.violations:
            print(f"Violation: {var}")

    # type checking
    type_check_visitor = ConstraintVisitorTypeCheck()
    try:
        type_check_visitor.var_symbol_table = declaration_collector.var_symbol_table
        type_check_visitor.function_table = declaration_collector.func_symbol_table
        type_check_visitor.struct_definitions = declaration_collector.struct_definitions
        type_check_visitor.visit(tree)
    except Exception as e:
        # print the traceback
        traceback.print_exc()   

    if should_print:
        print("=== Type Check Visitor ===")
        for var in type_check_visitor.violations:
            print(f"Violation: {var}")

    # For debugging, just return 0 so we can look and see
    # what the counts are
    # return 0

    # Try just the node goal visitor
    # This will never produce anything.
    # return 1 if node_goal_visitor.node_count < 1000 else 0

    # Return number of violations
    return len(reasonable_size_visitor.violations) + \
           len(def_use_visitor.violations) + \
           len(return_in_func_visitor.violations) + \
           len(struct_access_visitor.violations) + \
           len(no_void_decl_visitor.violations) + \
           len(struct_expr_rhs_of_decl_visitor.violations) + \
           len(no_empty_struct_visitor.violations) + \
           len(type_check_visitor.violations) + \
           len(declaration_collector.violations) + \
           len(no_duplicate_struct_fields_visitor.violations)